    $Idx = $NewLines.IndexOf("[Privilege Rights]")
    if ($Idx -ge 0) {
        $NewLines.Insert($Idx + 1, "SeTakeOwnershipPrivilege = *S-1-5-32-544")
    } else {
        $NewLines += "SeTakeOwnershipPrivilege = *S-1-5-32-544"
    }
}

