    "MaxServiceTicketAge"          = 600
    "MaxTicketAge"                 = 10
    "MaxRenewAge"                  = 7
    "MaxClockSkew"                 = 5
    "TicketValidateClient"         = 1
}

foreach ($Line in $Lines) {
    if ($Line -match "^\[(.*)\]$") {
        $SectionName = $Matches[1]
        if ($SectionName -eq "System Access") {
