function Test-RegValue { param( [string]$RecNum, [string]$Hive, [string]$KeyPath, [string]$ValueName, [object]$ExpectedValue ) $FullPath = "$($Hive):\$($KeyPath)" if (Test-Path $FullPath) { $Prop = Get-ItemProperty -Path $FullPath -Name $ValueName -ErrorAction SilentlyContinue if ($null -ne $Prop) { $ActualValue = $Prop.$ValueName if ($ActualValue -eq $ExpectedValue) { Write-Host " [+] $RecNum | $ValueName = $ActualValue (Secure)" -ForegroundColor Green } else { Write-Host " [!] MISMATCH: $RecNum | Path: $Hive\$KeyPath | Value: $ValueName | Current: $ActualValue (Expected: $ExpectedValue)" -ForegroundColor Red $script:Vulnerable = $true } } else { Write-Host " [!] MISSING VALUE: $RecNum | Path: $Hive\$KeyPath | Value: $ValueName (Expected: $ExpectedValue)" -ForegroundColor Red $script:Vulnerable = $true } } else { Write-Host " [!] MISSING KEY: $RecNum | Path: $Hive\$KeyPath (Expected: $ValueName = $ExpectedValue)" -ForegroundColor Red $script:Vulnerable = $true } }
